  "action": "question",
  "question_count": 1,
  "is_atomic": true,
  "atomic_questions": [
    "How should domestic GDP be measured in this model — is it the total value of all four domestically produced goods (steel, engines, electronics, plastic) valued at the world-market prices you listed, or is it something else such as the value of final goods only (excluding intermediate inputs) or a net value after subtracting the cost of imported goods?"
  ],
  "rationale": "The response asks for a single policy choice regarding the definition of domestic GDP, presenting mutually exclusive options within one sentence."
}

{
  "action": "question",
